const $=s=>document.querySelector(s);let papers=[];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function render(){const q=$('#search').value.trim().toLowerCase(),f=$('#filter').value;const shown=papers.filter(p=>(!f||p.tag===f)&&JSON.stringify(p).toLowerCase().includes(q));$('#count').textContent=`顯示 ${shown.length} 篇文獻`;
$('#papers').innerHTML=shown.length?shown.map(p=>`<details class="paper" id="${esc(p.id)}"><summary><span class="tag">${esc(p.tag)}</span><span class="year">${p.year} · ${esc(p.journal)}</span><h3>${esc(p.title)}</h3><p>${esc(p.summary)}</p></summary><div class="paper-body"><p class="meta">${esc(p.original)}<br>${esc(p.authors)} · <a target="_blank" rel="noopener noreferrer" href="https://doi.org/${encodeURI(p.doi)}">閱讀原文 ↗</a></p><p class="scope">閱讀範圍：${esc(p.scope)} · 更新：2026-11-12</p><h3>RL 閱讀定位</h3><div class="rl">${[['STATE',p.state],['ACTION',p.action],['REWARD',p.reward],['EVALUATION',p.evaluation]].map(([k,v])=>`<div><b>${k}</b>${esc(v)}</div>`).join('')}</div><div class="notes">${['動機','方法','圖表解析','專題應用','注意事項與新方法','結論','報告提問'].map((h,i)=>`<h4>${String(i+1).padStart(2,'0')} ／ ${h}</h4><p>${esc(p.notes[i])}</p>`).join('')}</div><div class="related"><b>延伸閱讀 · 編輯推薦，非即時搜尋</b>${papers.filter(r=>r.id!==p.id).map(r=>`<a href="#${r.id}" data-open="${r.id}">${esc(r.title)} ↗</a><span>推薦理由：補充${esc(r.tag)}的閱讀視角。</span>`).join('')}</div></div></details>`).join(''):'<p>沒有符合的文獻，請試試其他關鍵字。</p>';
 document.querySelectorAll('[data-open]').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();const id=a.dataset.open;$('#search').value='';$('#filter').value='';render();const d=document.getElementById(id);d.open=true;d.scrollIntoView({behavior:'smooth'});history.replaceState(null,'','#'+id)}));}
fetch('data/papers.json').then(r=>{if(!r.ok)throw Error('data');return r.json()}).then(data=>{papers=data;render();if(location.hash){const d=document.getElementById(location.hash.slice(1));if(d?.tagName==='DETAILS')d.open=true}}).catch(()=>$('#papers').textContent='文獻資料暫時無法載入，請重新整理，或以本機伺服器開啟網站。');
$('#search').addEventListener('input',render);$('#filter').addEventListener('change',render);
$('#copy').addEventListener('click',async()=>{const text=$('.prompt p').textContent;try{await navigator.clipboard.writeText(text);$('#copy-status').textContent='已複製'}catch{$('#copy-status').textContent='請選取上方文字手動複製'}});
